  function WIZ_0(){ return [["Compare & Match", "1", "[{\"id\":\"ad42d906874a0310fb15653f8bbb35bc\",\"name\":\"akshit mahajan\"}]", "OPS Shared Services", "{}", "", "Real-time", "[{\"excludeNoise\":true,\"keywords\":\"settlement instruction, value date, deal reference, trade confirmation, pay, receive, FXOPT\",\"subject\":\"settlement, confirmation, FXOPT\",\"name\":\"\",\"context\":\"Outbound OTC FX settlement instructions and trade confirmations — value date, amount, currency, pay/receive direction, and a trade/deal reference. Not entity static-data or reference-data change notices.\",\"exclusions\":\"NLUX\",\"excludeReplies\":true,\"senders\":\"\"}]", "Mail", "[{\"name\":\"Value Date\",\"type\":\"string\",\"prompt\":\"Extract the settlement / value date for this cashflow. It may appear under a value-date column or label, after the word 'value', in a key/value line, inside a SWIFT date-and-amount field, or — only when the body contains none — in the subject line. The source date may be written in ISO, day-first, or day-month-name form, or as a compact SWIFT date; interpret whichever is present. Always return the date in ISO format YYYY-MM-DD. If it is genuinely absent, return an empty string.\",\"example\":\"\",\"value\":\"2026-06-13\",\"custom\":false,\"mapExclude\":false,\"examples\":[\"2026-06-13\",\"2026-06-14\",\"2026-06-05\"]},{\"name\":\"Amount\",\"type\":\"float\",\"prompt\":\"Extract the settlement amount for this cashflow — the cash amount to settle, not the trade notional. The column may be labelled Amount, Flow Amount or Quantity; that value is the settlement amount. Strip any currency symbol and thousands separators. Where a comma is used as the decimal separator, convert it to a dot. Preserve the sign — negative amounts must stay negative. Return the number only, using a dot as the decimal separator. If it is absent, return an empty string.\",\"example\":\"\",\"value\":\"1497447.18\",\"custom\":false,\"mapExclude\":false,\"examples\":[\"1497447.18\",\"690397.75\",\"-2309184.24\"]},{\"name\":\"Currency\",\"type\":\"string\",\"prompt\":\"Extract the settlement currency for this cashflow as a three-letter ISO 4217 code. It may appear under a currency column or label, in a key/value line, embedded inside a SWIFT date-and-amount field, or as the first token of a shorthand amount line. Return the uppercase three-letter code only. If it is absent, return an empty string.\",\"example\":\"\",\"value\":\"EUR\",\"custom\":false,\"mapExclude\":false,\"examples\":[\"EUR\",\"SGD\",\"AUD\"]},{\"name\":\"Direction\",\"type\":\"string\",\"prompt\":\"Extract the settlement direction for this cashflow from the counterparty's stated point of view — return exactly 'Pay' or 'Receive'. Normalise single-letter indicators, SWIFT direction tags, and combined Pay/Receive columns to the full word. In shorthand lines the direction indicator follows the currency. If the email states no direction (for example a fund or quantity table with no Pay/Receive column), return an empty string — do not infer it from the amount's sign.\",\"example\":\"\",\"value\":\"Pay\",\"custom\":false,\"mapExclude\":false,\"examples\":[\"Pay\",\"Receive\",\"Pay\"]}]", "Email", "email1@outlook.com", "{\"Value Date\":\"value_date\",\"Amount\":\"amount\",\"Currency\":\"currency\",\"Direction\":\"direction\"}", "OTC Settlement : Prematching", "Pre Settlement", "published", "OTC Settlements", "[{\"stage\":\"Default\",\"tag\":\"\"},{\"stage\":\"Extraction Confirmed\",\"tag\":\"\"},{\"stage\":\"Review Confirmed\",\"tag\":\"\"},{\"stage\":\"Resolved\",\"tag\":\"\"},{\"stage\":\"Escalated\",\"tag\":\"\"}]", "PCM", "v1", "Cash flow & SSI confirmation (Int \\ Ext)", "[{\"scenario\":\"Matched\",\"actions\":[\"Send to NEWS\"]},{\"scenario\":\"Mismatch\",\"actions\":[\"Reply to Middle Office\"]},{\"scenario\":\"No Match\",\"actions\":[\"Reply to Counterparty\"]}]", "83425dc38383cb10fe5233b8beaad34f"]]; }
